  'lat_pulldown': ExerciseGuide(['Хват шире плеч, бёдра зафиксированы валиком.', 'Сначала опусти плечи, потом тяни рукоять к верху груди.', 'Медленно отпускай вверх до полного выпрямления рук.'], 'Раскачка корпусом и тяга за голову — тяни к груди, корпус почти неподвижен.'),
  'assisted_pull_up': ExerciseGuide(['Колени на платформу противовеса, хват чуть шире плеч. Противовес подбери так, чтобы 10–12 повторов давались с запасом.', 'Сведи лопатки и тянись грудью к перекладине, подбородок выше неё.', 'Опускайся медленно до прямых рук. Со временем уменьшай противовес — так придёшь к подтягиваниям.'], 'Слишком большой противовес и рывки — мышцы почти не работают. Медленно и подконтрольно.'),
  'negative_pull_up': ExerciseGuide(['Встань на опору так, чтобы подбородок был над перекладиной.', 'Сойди с опоры и опускайся медленно, 3–5 секунд.', 'Внизу встань на опору и повтори.'], 'Падение вниз за секунду — смысл в медленном опускании.'),
  'pull_up': ExerciseGuide(['Хват чуть шире плеч, повисни на прямых руках.', 'Сведи лопатки и тянись грудью к перекладине.', 'Опускайся полностью, без рывка.'], 'Рывки ногами и неполная амплитуда. Не выходит — начни с негативов.'),
  'weighted_pull_up': ExerciseGuide(['Пояс с блином или гантель между стоп; повисни на прямых руках, хват чуть шире плеч.', 'Сведи лопатки и тянись грудью к перекладине, подбородок выше неё.', 'Опускайся полностью и медленно, вес не раскачивается.'], 'Брать вес, пока 8 чистых подтягиваний без него не выходят: техника ломается, плечи перегружаются.'),
  'db_row': ExerciseGuide(['Колено и ладонь на скамье, спина прямая и параллельна полу.', 'Тяни гантель к поясу, локоть идёт вдоль корпуса.', 'Опускай под контролем до полного растяжения.'], 'Скручивание корпуса ради веса — лучше взять легче и тянуть спиной.'),
  'seated_cable_row': ExerciseGuide(['Сядь, колени чуть согнуты, спина прямая.', 'Тяни рукоять к животу, сводя лопатки.', 'Отпускай вперёд, не округляя спину.'], 'Корпус качается назад-вперёд — двигаются только руки и лопатки.'),
  'barbell_row': ExerciseGuide(['Наклон корпуса около 45°, колени чуть согнуты, спина прямая.', 'Тяни гриф к низу живота, локти вдоль корпуса.', 'Опускай под контролем, не меняя наклон.'], 'Корпус выпрямляется с каждым повтором — возьми вес легче.'),
  'face_pull': ExerciseGuide(['Блок на уровне лица, хват канатом сверху.', 'Тяни канат к лицу, разводя концы и локти в стороны.', 'Задержись на секунду и медленно верни.'], 'Тяжёлый вес и рывки — это упражнение для осанки, работай легко и чисто.'),
  'bodyweight_squat': ExerciseGuide(['Стопы на ширине плеч, носки слегка врозь.', 'Отводи таз назад и вниз, колени идут по линии носков.', 'Опустись до параллели бёдер с полом и встань через пятки.'], 'Колени заваливаются внутрь — толкай их наружу, по линии стоп.'),
  'leg_press': ExerciseGuide(['Поясница прижата к спинке, стопы на ширине плеч в центре платформы.', 'Опускай платформу, пока колени не согнутся примерно до 90°.', 'Выжимай, не выпрямляя колени до замка.'], 'Таз отрывается от сиденья внизу — уменьши амплитуду.'),
  'goblet_squat': ExerciseGuide(['Держи гантель вертикально у груди, локти вниз.', 'Приседай между коленями, корпус почти вертикален.', 'Встань, толкая пол всей стопой.'], 'Гантель отходит от груди и тянет корпус вперёд — прижми её.'),
  'barbell_squat': ExerciseGuide(['Гриф на трапециях, лопатки сведены, взгляд вперёд.', 'Вдох, напряги пресс, приседай, отводя таз назад.', 'До параллели и выше, спина нейтральная, пятки на полу.'], 'Округление спины внизу — уменьши вес и глубину, укрепи кор.'),
  'leg_extension': ExerciseGuide(['Валик на голеностопе, колено на оси тренажёра.', 'Разгибай ноги до почти прямых.', 'Опускай медленно, без броска.'], 'Бросок веса вниз и рывок вверх — колени любят плавность.'),
  'lunges': ExerciseGuide(['Шаг вперёд, корпус вертикально.', 'Опускайся, пока заднее колено почти не коснётся пола.', 'Оттолкнись передней ногой и вернись.'], 'Переднее колено уходит внутрь — держи его над стопой.'),
  'bulgarian_split_squat': ExerciseGuide(['Задняя стопа на скамье, передняя — на шаг впереди.', 'Опускайся вниз, корпус чуть наклонён вперёд.', 'Встань, толкая пол передней пяткой.'], 'Слишком короткий шаг — колено уходит далеко за носок. Отставь ногу дальше.'),
