  'back_extension': ExerciseGuide(['Валик под тазовыми костями, руки на груди или за головой.', 'Опускайся с прямой спиной, сгибаясь в тазобедренном суставе.', 'Поднимайся до прямой линии тела, не выше.'], 'Переразгибание вверху — заканчивай в прямой линии.'),
  'leg_curl': ExerciseGuide(['Валик над пятками, колени у края скамьи.', 'Сгибай ноги, подтягивая валик к ягодицам.', 'Опускай медленно, не отрывая таз.'], 'Таз поднимается со скамьи — вес великоват.'),
  'romanian_deadlift': ExerciseGuide(['Колени чуть согнуты, гриф или гантели у бёдер.', 'Отводи таз назад, вес скользит вдоль ног до середины голени.', 'Почувствуй растяжение бицепса бедра и вернись, толкая таз вперёд.'], 'Круглая спина — опускай вес только пока спина прямая.'),
  'deadlift': ExerciseGuide(['Гриф над серединой стопы, хват чуть шире ног, спина прямая.', 'Вдох, напряги пресс и толкай пол ногами, гриф идёт вдоль ног.', 'Наверху выпрямись без прогиба назад, опускай тем же путём.'], 'Округление спины при отрыве — главная ошибка. Вес меньше, спина ровная.'),
  'calf_raise': ExerciseGuide(['Носки на ступеньке, пятки свисают.', 'Поднимись на носки как можно выше.', 'Опустись ниже уровня ступеньки до растяжения икр.'], 'Пружинящие короткие повторы — двигайся во всю амплитуду.'),
  'db_shoulder_press': ExerciseGuide(['Сядь со спинкой, гантели у плеч, ладони вперёд.', 'Выжимай вверх, не сводя гантели до удара.', 'Опускай до уровня ушей под контролем.'], 'Прогиб в пояснице — прижми спину и напряги пресс.'),
  'overhead_press': ExerciseGuide(['Гриф на верху груди, хват чуть шире плеч, ягодицы и пресс напряжены.', 'Выжимай гриф вверх, убирая голову назад, а потом под гриф.', 'Опускай к груди под контролем.'], 'Сильный прогиб назад, чтобы выжать вес, — это нагрузка на поясницу. Вес легче.'),
  'lateral_raise': ExerciseGuide(['Стоя, гантели у бёдер, локти чуть согнуты.', 'Поднимай руки в стороны до уровня плеч.', 'Опускай медленно, не роняя.'], 'Раскачка и подъём выше плеч — работают трапеции, а не дельты.'),
  'db_curl': ExerciseGuide(['Стоя, локти прижаты к корпусу.', 'Сгибай руки, разворачивая ладони к плечам.', 'Опускай медленно до почти прямых рук.'], 'Раскачка корпусом — значит вес тяжёлый, возьми легче.'),
  'hammer_curl': ExerciseGuide(['Гантели у бёдер, ладони смотрят друг на друга.', 'Сгибай руки, не разворачивая кисти.', 'Опускай под контролем.'], 'Локти уезжают вперёд — держи их у корпуса.'),
  'barbell_curl': ExerciseGuide(['Хват снизу на ширине плеч, локти у корпуса.', 'Сгибай руки, поднимая гриф к груди.', 'Опускай медленно, без рывка корпусом.'], 'Читинг спиной на каждом повторе — вес великоват.'),
  'bench_dips': ExerciseGuide(['Ладони на краю скамьи позади себя, ноги вперёд.', 'Опускай таз, сгибая локти примерно до 90°.', 'Разгибай руки, поднимаясь вверх.'], 'Опускание слишком глубоко тянет плечи — хватит 90° в локтях.'),
  'triceps_pushdown': ExerciseGuide(['Стоя у верхнего блока, локти прижаты к бокам.', 'Разгибай руки вниз до прямых.', 'Возвращай медленно, локти не двигаются.'], 'Локти гуляют вперёд-назад — работает спина вместо трицепса.'),
  'french_press': ExerciseGuide(['Лёжа, гриф или гантели над лбом на прямых руках.', 'Сгибай руки только в локтях, опуская вес ко лбу.', 'Разгибай, локти смотрят вверх и не расходятся.'], 'Локти разъезжаются в стороны — держи их на ширине плеч.'),
  'dead_bug': ExerciseGuide(['Лёжа на спине, руки вверх, колени над тазом под 90°.', 'Опускай противоположные руку и ногу к полу.', 'Поясница всё время прижата к полу, верни и поменяй сторону.'], 'Поясница отрывается от пола — уменьши амплитуду.'),
  'plank': ExerciseGuide(['Упор на предплечьях, локти под плечами.', 'Тело прямое, пресс и ягодицы напряжены.', 'Дыши ровно, держи положение.'], 'Провисание поясницы — лучше короче, но ровно.'),
  'crunches': ExerciseGuide(['Лёжа, колени согнуты, руки у висков.', 'Скручивайся, отрывая лопатки от пола, поясница прижата.', 'Медленно возвращайся, не роняя голову.'], 'Тянуть голову руками — работает пресс, а не шея.'),
  'weighted_crunch': ExerciseGuide(['Лёжа, колени согнуты, гантель или блин прижат к груди.', 'Скручивайся, отрывая лопатки от пола, поясница прижата.', 'Опускайся медленно, не бросая вес.'], 'Рывок корпусом и вес за головой — нагрузка уходит в шею и поясницу.'),
  'cable_crunch': ExerciseGuide(['Встань на колени лицом к верхнему блоку, канат у головы.', 'Скручивайся вниз, сводя рёбра к тазу; бёдра неподвижны.', 'Медленно возвращайся вверх, пресс не расслабляй.'], 'Тянуть руками и садиться тазом на пятки — работать должен пресс.'),
  'side_plank': ExerciseGuide(['Упор на предплечье, локоть под плечом, ноги вместе.', 'Подними таз до прямой линии тела.', 'Держи, затем смени сторону — время на одну сторону.'], 'Таз проваливается к полу — лучше короче, но в линию.'),
  'russian_twist': ExerciseGuide(['Сидя, корпус отклонён назад, стопы на полу или чуть приподняты.', 'Поворачивай корпус, касаясь руками пола сбоку.', 'Счёт — касания с обеих сторон вместе.'], 'Двигаются только руки — поворачивай плечи вместе с ними.'),
  'hanging_leg_raise': ExerciseGuide(['Вис на перекладине, плечи активны.', 'Поднимай ноги, подкручивая таз к груди.', 'Опускай медленно, без раскачки.'], 'Махи по инерции — останови раскачку перед каждым повтором.'),
  'warm_bike': ExerciseGuide(['Сопротивление низкое, темп разговорный.', 'Под конец чуть ускорься.'], 'Разминка — не тренировка: если запыхался, сбавь.'),
  'warm_rower': ExerciseGuide(['Толчок ногами, затем корпус, затем руки.', 'Возврат в обратном порядке, спокойно.'], 'Тянуть руками раньше ног — главная работа у ног.'),
  'warm_march': ExerciseGuide(['Поднимай колени до уровня таза, руки работают.', 'Темп бодрый, но без прыжков.'], 'Сутулая спина — держи корпус ровно.'),
  'warm_jumping_jacks': ExerciseGuide(['Прыжком ноги врозь, руки над головой.', 'Прыжком обратно, руки к бёдрам.'], 'Приземление на пятки — мягко на носки.'),
  'warm_arm_circles': ExerciseGuide(['Руки в стороны, начни с маленьких кругов.', 'Постепенно увеличивай круги, потом смени направление.'], 'Поднятые к ушам плечи — опусти их.'),
  'warm_wall_push_up': ExerciseGuide(['Ладони на стене на уровне груди.', 'Сгибай руки, приближая грудь к стене, и выжимайся.'], 'Спешка — разминка медленная и полная по амплитуде.'),
  'warm_band_pull': ExerciseGuide(['Руки перед собой на уровне плеч (с резинкой или без).', 'Разводи руки в стороны, сводя лопатки.'], 'Прогиб в пояснице — двигаются только руки и лопатки.'),
  'warm_cat_cow': ExerciseGuide(['Стоя на четвереньках, на выдохе округли спину.', 'На вдохе прогнись, взгляд вперёд.'], 'Резкие движения — плавно, с дыханием.'),
  'warm_torso_twist': ExerciseGuide(['Стопы на ширине плеч, руки перед грудью.', 'Поворачивайся вправо и влево, таз смотрит вперёд.'], 'Рывки в конце поворота — мягко.'),
  'warm_hip_circles': ExerciseGuide(['Руки на поясе, ноги на ширине плеч.', 'Широкие круги тазом в одну сторону, потом в другую.'], 'Движутся плечи — работает только таз.'),
  'warm_leg_swings': ExerciseGuide(['Держись за опору, маши ногой вперёд-назад.', '10 на каждую ногу, амплитуда растёт постепенно.'], 'Махи с размаху до боли — амплитуда растёт сама.'),
  'warm_squat': ExerciseGuide(['Присядь до комфортной глубины.', 'С каждым повтором чуть глубже.'], 'Сразу в полную глубину — дай суставам привыкнуть.'),
  'warm_good_morning': ExerciseGuide(['Руки за головой, колени чуть согнуты.', 'Наклоняйся, отводя таз назад, спина прямая.'], 'Круглая спина — наклоняйся только пока спина ровная.'),
  'warm_inchworm': ExerciseGuide(['Наклонись, поставь ладони на пол.', 'Переступай руками в упор лёжа и обратно к ногам.'], 'Провисание в упоре лёжа — держи пресс.'),
